Type hints allow you to add type information to your code, which can be used by static type checkers like mypy.

### Basic Type Hints

```python
from typing import List, Dict, Optional, Union, Tuple, Callable
from dataclasses import dataclass

def greet(name: str, age: int = 18) -> str:
    return f"Hello {name}, you are {age} years old"

def calculate_average(numbers: List[float]) -> float:
    if not numbers:
        return 0.0
    return sum(numbers) / len(numbers)

def process_user_data(
    user_id: int,
    data: Dict[str, Union[str, int, float]],
    callback: Optional[Callable[[str], None]] = None
) -> Tuple[bool, str]:
    try:
        # Process the data
        result = f"Processed data for user {user_id}"
        if callback:
            callback(result)
        return True, result
    except Exception as e:
        return False, str(e)

# Usage
print(greet("Alice", 25))
print(calculate_average([1.5, 2.5, 3.5, 4.5]))

def log_message(message: str):
    print(f"LOG: {message}")

success, result = process_user_data(
    123, 
    {"name": "Alice", "age": 25, "score": 95.5},
    log_message
)
print(f"Success: {success}, Result: {result}")
```

### Advanced Type Hints

```python
from typing import TypeVar, Generic, Protocol, runtime_checkable
from abc import ABC, abstractmethod

# Type variables for generic types
T = TypeVar('T')
K = TypeVar('K')
V = TypeVar('V')

# Generic class
class Stack(Generic[T]):
    def __init__(self) -> None:
        self._items: List[T] = []

    def push(self, item: T) -> None:
        self._items.append(item)

    def pop(self) -> T:
        if not self._items:
            raise IndexError("Stack is empty")
        return self._items.pop()

    def peek(self) -> T:
        if not self._items:
            raise IndexError("Stack is empty")
        return self._items[-1]

    def is_empty(self) -> bool:
        return len(self._items) == 0

# Protocol (structural typing)
@runtime_checkable
class Drawable(Protocol):
    def draw(self) -> str:
        ...

class Circle:
    def __init__(self, radius: float):
        self.radius = radius

    def draw(self) -> str:
        return f"Drawing circle with radius {self.radius}"

class Rectangle:
    def __init__(self, width: float, height: float):
        self.width = width
        self.height = height

    def draw(self) -> str:
        return f"Drawing rectangle {self.width}x{self.height}"

def draw_shape(shape: Drawable) -> str:
    return shape.draw()

# Usage
int_stack = Stack[int]()
int_stack.push(1)
int_stack.push(2)
int_stack.push(3)
print(f"Popped: {int_stack.pop()}")  # 3

string_stack = Stack[str]()
string_stack.push("hello")
string_stack.push("world")
print(f"Peek: {string_stack.peek()}")  # world

# Using protocols
circle = Circle(5.0)
rectangle = Rectangle(10.0, 5.0)

print(draw_shape(circle))      # Drawing circle with radius 5.0
print(draw_shape(rectangle))   # Drawing rectangle 10.0x5.0

# Runtime checking
print(isinstance(circle, Drawable))      # True
print(isinstance(rectangle, Drawable))   # True
```

**What this code covers**

- Abstract base class for data processing
- Process the input data
- Validate the input data
- Get information about the processor

**Defines:** `DataProcessor`, `TextProcessor`, `NumberProcessor`, `Database`, `MySQLDatabase`

Abstract Base Classes provide a way to define interfaces and enforce implementation of abstract methods.

### Basic ABCs

```python
from abc import ABC, abstractmethod
from typing import List, Dict, Any

class DataProcessor(ABC):
    """Abstract base class for data processing"""

    @abstractmethod
    def process(self, data: Any) -> Any:
        """Process the input data"""
        pass

    @abstractmethod
    def validate(self, data: Any) -> bool:
        """Validate the input data"""
        pass

    def get_info(self) -> str:
        """Get information about the processor"""
        return f"Processor: {self.__class__.__name__}"

class TextProcessor(DataProcessor):
    def process(self, data: str) -> str:
        if not self.validate(data):
            raise ValueError("Invalid text data")
        return data.upper()

    def validate(self, data: Any) -> bool:
        return isinstance(data, str) and len(data) > 0

class NumberProcessor(DataProcessor):
    def process(self, data: List[float]) -> float:
        if not self.validate(data):
            raise ValueError("Invalid number data")
        return sum(data) / len(data)

    def validate(self, data: Any) -> bool:
        return isinstance(data, list) and all(isinstance(x, (int, float)) for x in data)

# Usage
text_processor = TextProcessor()
number_processor = NumberProcessor()

print(text_processor.process("hello world"))  # HELLO WORLD
print(number_processor.process([1, 2, 3, 4, 5]))  # 3.0

print(text_processor.get_info())  # Processor: TextProcessor
print(number_processor.get_info())  # Processor: NumberProcessor
```

### Advanced ABCs with Properties

```python
from abc import ABC, abstractmethod, abstractproperty
from typing import Dict, Any

class Database(ABC):
    """Abstract database interface"""

    @property
    @abstractmethod
    def connection_string(self) -> str:
        """Get the database connection string"""
        pass

    @abstractmethod
    def connect(self) -> bool:
        """Connect to the database"""
        pass

    @abstractmethod
    def disconnect(self) -> bool:
        """Disconnect from the database"""
        pass

    @abstractmethod
    def execute_query(self, query: str) -> List[Dict[str, Any]]:
        """Execute a database query"""
        pass

    @abstractmethod
    def execute_command(self, command: str) -> int:
        """Execute a database command"""
        pass

class MySQLDatabase(Database):
    def __init__(self, host: str, port: int, database: str, username: str, password: str):
        self._host = host
        self._port = port
        self._database = database
        self._username = username
        self._password = password
        self._connected = False

    @property
    def connection_string(self) -> str:
        return f"mysql://{self._username}@{self._host}:{self._port}/{self._database}"

    def connect(self) -> bool:
        # Simulate connection
        print(f"Connecting to MySQL: {self.connection_string}")
        self._connected = True
        return True

    def disconnect(self) -> bool:
        if self._connected:
            print("Disconnecting from MySQL")
            self._connected = False
        return True

    def execute_query(self, query: str) -> List[Dict[str, Any]]:
        if not self._connected:
            raise ConnectionError("Not connected to database")
        print(f"Executing query: {query}")
        return [{"id": 1, "name": "Alice"}, {"id": 2, "name": "Bob"}]

    def execute_command(self, command: str) -> int:
        if not self._connected:
            raise ConnectionError("Not connected to database")
        print(f"Executing command: {command}")
        return 1  # Number of affected rows

# Usage
mysql_db = MySQLDatabase("localhost", 3306, "mydb", "user", "password")
print(f"Connection string: {mysql_db.connection_string}")

mysql_db.connect()
results = mysql_db.execute_query("SELECT * FROM users")
print(f"Query results: {results}")

affected_rows = mysql_db.execute_command("INSERT INTO users (name) VALUES ('Charlie')")
print(f"Affected rows: {affected_rows}")

mysql_db.disconnect()
```

The `__slots__` attribute allows you to explicitly declare which attributes a class can have, providing memory optimization and faster attribute access.

### Basic Slots Usage

```python
class Person:
    __slots__ = ['name', 'age', 'email']

    def __init__(self, name: str, age: int, email: str = None):
        self.name = name
        self.age = age
        self.email = email

    def get_info(self) -> str:
        return f"{self.name} ({self.age} years old)"

class Employee(Person):
    __slots__ = ['employee_id', 'salary']  # Inherits parent slots

    def __init__(self, name: str, age: int, employee_id: str, salary: float, email: str = None):
        super().__init__(name, age, email)
        self.employee_id = employee_id
        self.salary = salary

    def get_info(self) -> str:
        base_info = super().get_info()
        return f"{base_info} - Employee ID: {self.employee_id}"

# Usage
person = Person("Alice", 30, "alice@example.com")
employee = Employee("Bob", 25, "EMP001", 50000, "bob@example.com")

print(person.get_info())
print(employee.get_info())

# This would raise an AttributeError
# person.address = "123 Main St"  # AttributeError: 'Person' object has no attribute 'address'
```

### Advanced Slots with Descriptors

```python
class ValidatedAttribute:
    """Descriptor for validated attributes"""

    def __init__(self, min_value=None, max_value=None, allowed_values=None):
        self.min_value = min_value
        self.max_value = max_value
        self.allowed_values = allowed_values
        self.name = None

    def __set_name__(self, owner, name):
        self.name = name

    def __get__(self, instance, owner):
        if instance is None:
            return self
        return instance.__dict__.get(self.name)

    def __set__(self, instance, value):
        if self.min_value is not None and value < self.min_value:
            raise ValueError(f"{self.name} must be at least {self.min_value}")
        if self.max_value is not None and value > self.max_value:
            raise ValueError(f"{self.name} must be at most {self.max_value}")
        if self.allowed_values is not None and value not in self.allowed_values:
            raise ValueError(f"{self.name} must be one of {self.allowed_values}")
        instance.__dict__[self.name] = value

class Product:
    __slots__ = ['_name', '_price', '_category', '_stock']

    name = ValidatedAttribute(allowed_values=['Electronics', 'Clothing', 'Books', 'Food'])
    price = ValidatedAttribute(min_value=0.0)
    category = ValidatedAttribute(allowed_values=['Electronics', 'Clothing', 'Books', 'Food'])
    stock = ValidatedAttribute(min_value=0)

    def __init__(self, name: str, price: float, category: str, stock: int = 0):
        self.name = name
        self.price = price
        self.category = category
        self.stock = stock

    def add_stock(self, quantity: int):
        if quantity > 0:
            self.stock += quantity

    def remove_stock(self, quantity: int):
        if quantity > 0 and self.stock >= quantity:
            self.stock -= quantity
        else:
            raise ValueError("Insufficient stock")

    def get_info(self) -> str:
        return f"{self.name} - {self.category} - ${self.price} - Stock: {self.stock}"

# Usage
try:
    product = Product("Laptop", 999.99, "Electronics", 10)
    print(product.get_info())

    product.add_stock(5)
    print(f"After adding stock: {product.stock}")

    product.remove_stock(3)
    print(f"After removing stock: {product.stock}")

    # This would raise ValueError
    # product.price = -100  # ValueError: price must be at least 0.0

except ValueError as e:
    print(f"Error: {e}")
```
